        "ai.llms-links": Guidance("Correct or remove the dead links in /llms.txt."),
        "hreflang.noncanonical": Guidance("Put the hreflang tags on the canonical page, or correct the canonical if it is the mistake."),
        "hreflang.target": Guidance("Point each hreflang link at the final address of a page that loads and is not set to noindex."),
        "hreflang.duplicate": Guidance("Keep one address for each language and region, and delete the other tag.",
